class Solution {
  public int minSwaps(int[] nums, int[] forbidden) {
    int n = nums.length;
    java.util.HashMap<Integer, Integer> numCount = new java.util.HashMap<>(),
        forbCount = new java.util.HashMap<>(),
        conflictCount = new java.util.HashMap<>();
    int conflicts = 0;
    for (int i = 0; i < n; i++) {
      numCount.merge(nums[i], 1, Integer::sum);
      forbCount.merge(forbidden[i], 1, Integer::sum);
      if (nums[i] == forbidden[i]) {
        conflicts++;
        conflictCount.merge(nums[i], 1, Integer::sum);
      }
    }
    for (java.util.Map.Entry<Integer, Integer> e : numCount.entrySet()) {
      if (e.getValue() + forbCount.getOrDefault(e.getKey(), 0) > n) return -1;
    }
    int maxConflict = 0;
    for (int c : conflictCount.values()) maxConflict = Math.max(maxConflict, c);
    return Math.max((conflicts + 1) / 2, maxConflict);
  }
}
